"""Coverage calibration, score filtering and table-entry accounting.

The legacy coverage filter sampled generators and printed progress to stderr;
the contract instead needs exact per-class validation coverage of every
generalized interval, an exact rational score and the resulting kept/priority
selection shared across classes and lengths.
"""
from collections import defaultdict
from fractions import Fraction
from itertools import product

import numpy as np

PAD = 1514
VALUE_MAX = 3028
SCORE_FLOOR = Fraction(1, 10000)
CELL_BUDGET = 1 << 22


def _row_matrix(rows):
    """Padded int16 matrix of real prefixes; padding never matches a bound."""
    count = len(rows)
    widest = 0
    for _, values in rows:
        if len(values) > widest:
            widest = len(values)
    matrix = np.full((count, widest), -1, dtype=np.int16)
    lengths = np.zeros(count, dtype=np.int64)
    labels = np.zeros(count, dtype=np.int64)
    low = np.full(count, VALUE_MAX+1, dtype=np.int32)
    high = np.full(count, -1, dtype=np.int32)
    for index, (label, values) in enumerate(rows):
        size = len(values)
        labels[index] = label
        lengths[index] = size
        if size:
            matrix[index, :size] = values
            low[index] = min(values)
            high[index] = max(values)
    return matrix, lengths, labels, low, high


def _usable_rows(matrix, low, high, labels, lengths, length):
    usable = lengths >= length
    if not usable.any():
        return None
    if usable.all():
        return matrix, low, high, labels
    return matrix[usable], low[usable], high[usable], labels[usable]


def _coverage(sub, low, high, labels, bounds, classes, length):
    """Validation rows holding at least one window inside every interval."""
    rows = sub.shape[0]
    possible = np.ones(rows, dtype=bool)
    for axis in range(length):
        lo, hi = bounds[axis]
        possible &= (low <= hi) & (high >= lo)
    chosen = np.nonzero(possible)[0]
    if chosen.size == 0:
        return [0]*classes
    block = sub if chosen.size == rows else sub[chosen]
    picked = labels if chosen.size == rows else labels[chosen]
    window = block.shape[1]-length+1
    lo, hi = bounds[0]
    row_index, offset = np.nonzero((block[:, 0:window] >= lo) & (block[:, 0:window] <= hi))
    for axis in range(1, length):
        if row_index.size == 0:
            break
        lo, hi = bounds[axis]
        values = block[row_index, offset+axis]
        keep = (values >= lo) & (values <= hi)
        row_index = row_index[keep]
        offset = offset[keep]
    if row_index.size == 0:
        return [0]*classes
    hit = np.zeros(block.shape[0], dtype=bool)
    hit[row_index] = True
    return np.bincount(picked[hit], minlength=classes).tolist()


def calibrate(bounds_list, rows, classes):
    """Per-class matching validation-row counts for every interval pattern."""
    empty = [0]*classes
    if not rows:
        return [list(empty) for _ in bounds_list]
    matrix, lengths, labels, low, high = _row_matrix(rows)
    cache = {}
    views = {}
    results = []
    for bounds in bounds_list:
        key = tuple(tuple(pair) for pair in bounds)
        hits = cache.get(key)
        if hits is None:
            length = len(bounds)
            if length not in views:
                views[length] = _usable_rows(matrix, low, high, labels, lengths, length)
            view = views[length]
            if view is None:
                hits = list(empty)
            else:
                hits = _coverage(view[0], view[1], view[2], view[3], bounds, classes, length)
            cache[key] = hits
        results.append(hits)
    return results


def score_cluster(hits, counts, target):
    """Cin/(Cout+1/10000) with exact rational arithmetic."""
    inside = Fraction(hits[target], counts[target])
    outside = Fraction(0)
    for label in range(len(counts)):
        if label == target:
            continue
        candidate = Fraction(hits[label], counts[label])
        if candidate > outside:
            outside = candidate
    return inside/(outside+SCORE_FLOOR)


def priority_order(identities, scores, threshold):
    """Kept clusters by decreasing exact score, then increasing cluster id."""
    kept = [identity for identity in identities if scores[identity] > threshold]
    kept.sort(key=lambda identity: (-scores[identity], identity))
    return kept


def _key_count(bounds):
    total = 1
    for lo, hi in bounds:
        span = hi-lo+1
        if lo <= PAD <= hi:
            span -= 1
        if span <= 0:
            return 0
        total *= span
    return total


def _key_values(lo, hi):
    if lo <= PAD <= hi:
        return list(range(lo, PAD))+list(range(PAD+1, hi+1))
    return list(range(lo, hi+1))


def _drop_contained(boxes):
    """Remove boxes covered by another box of the same length."""
    size = len(boxes)
    if size <= 2:
        return boxes
    lows = np.array([box[0] for box in boxes], dtype=np.int32)
    highs = np.array([box[1] for box in boxes], dtype=np.int32)
    width = lows.shape[1]
    if size <= 48:
        keep = []
        for index in range(size):
            covered = False
            for other in range(size):
                if other != index and bool(np.all(lows[other] <= lows[index])) \
                        and bool(np.all(highs[index] <= highs[other])):
                    covered = True
                    break
            if not covered:
                keep.append(boxes[index])
        return keep
    keep = np.ones(size, dtype=bool)
    step = max(1, CELL_BUDGET//max(1, size*width))
    for start in range(0, size, step):
        stop = min(size, start+step)
        inner = ((lows[None, :, :] <= lows[start:stop, None, :]) &
                 (highs[start:stop, None, :] <= highs[None, :, :])).all(axis=-1)
        keep[start:stop] = inner.sum(axis=1) <= 1
    return [boxes[index] for index in range(size) if keep[index]]


def exact_entry_count(pattern_bounds, cap):
    """min(distinct exact keys, cap), excluding 1514 at every coordinate."""
    if not pattern_bounds:
        return 0
    if cap <= 1:
        for bounds in pattern_bounds:
            if _key_count(bounds) > 0:
                return cap
        return 0
    grouped = defaultdict(dict)
    for bounds in pattern_bounds:
        total = _key_count(bounds)
        if total == 0:
            continue
        if total >= cap:
            return cap
        grouped[len(bounds)][tuple(tuple(pair) for pair in bounds)] = (bounds, total)
    boxes = []
    for group in grouped.values():
        boxes.extend(_drop_contained(list(group.values())))
    boxes.sort(key=lambda item: -item[1])
    keys = set()
    for bounds, _ in boxes:
        axes = [_key_values(lo, hi) for lo, hi in bounds]
        for key in product(*axes):
            keys.add(key)
            if len(keys) >= cap:
                return cap
    return len(keys)
